(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0005.js"] = [{"id":"glyph-kai-62ef","script":"kai","character":"拯","reading":"zhěng","description":"zhěng：援救，救助～救。～饥。～弊（救正弊病）。～民于水火之中。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拯"},{"id":"glyph-kai-62f1","script":"kai","character":"拱","reading":"gǒng","description":"gǒng：(1)两手抱拳上举，以表敬意～手。～揖。\n(2)两手合围～抱。～木。～璧。\n(3)环绕～卫。～护。～北（众星环卫北极星）。\n(4)耸起，隆起，弯曲成弧形～肩缩背。～顶。～门。～桥。\n(5)向上或向前推，顶动～芽。虫子～土。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拱"},{"id":"glyph-kai-62f3","script":"kai","character":"拳","reading":"quán","description":"quán：(1)屈指卷（juǎn）握起来的手～头（头”读轻声）。\n(2)徒手的武术～术。打～。太极～。～谱。～脚。\n(3)肢体弯曲～曲。～起腿来。\n(4)量词，用于拳头打人的动作打他几～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拳"},{"id":"glyph-kai-62f4","script":"kai","character":"拴","reading":"shuān","description":"shuān：(1)用绳子系住，引申为打结～马。～车。\n(2)上闩门未～牢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拴"},{"id":"glyph-kai-62f7","script":"kai","character":"拷","reading":"kǎo","description":"kǎo：打～打。～问。～掠（泛指刑讯）。三～六问。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拷"},{"id":"glyph-kai-62fc","script":"kai","character":"拼","reading":"pīn","description":"pīn：(1)连合，凑合～凑。～音。～接。～写。七～八凑。\n(2)不顾一切地奋斗，豁出去～力。～刺。～搏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拼"},{"id":"glyph-kai-62fd","script":"kai","character":"拽","reading":"zhuài；zhuāi；yè","description":"zhuài：拉，牵引～住。～不动。\nzhuāi：(1)用力扔把球～过来。\n(2)胳膊有病，转动不灵。\nyè：同曳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拽"},{"id":"glyph-kai-62fe","script":"kai","character":"拾","reading":"shí；shè","description":"shí：(1)捡，从地上拿起～草。～粪。～零（捡取某方面的零碎材料，常用于文章标题）。～取。俯～皆是。～人牙慧。\n(2)收，敛，整理收～。～掇。\n(3)十”的大写。\n(4)旧称射箭人穿在左臂上的皮制护袖。\n丢；\nshè：古同涉”，历，经由～级而上。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拾"},{"id":"glyph-kai-62ff","script":"kai","character":"拿","reading":"ná","description":"ná：(1)用手取，握在手里～笔。～枪。\n(2)掌握，把握～主意。～权。～手。\n(3)挟（xié）制～捏（故意刁难人，要挟人）。～大（自以为比别人强，看不起人，摆架子）。\n(4)侵蚀，侵害让药水～白了。\n(5)逮捕，捉～获。擒～。～问。\n(6)攻下，占领一定要把敌人的碉堡～下来。\n(7)介绍，引出对象，相当于把”我～你当亲人看待。\n(8)介词，引出所凭借的工具、材料、方法等，相当于用”～笔来写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拿"},{"id":"glyph-kai-6301","script":"kai","character":"持","reading":"chí","description":"chí：(1)拿着，握住～笔。～枪。～牢（把稳）。\n(2)遵守不变坚～。～久。～操（保持节操）。～之以恒。\n(3)主张，掌管主～。～平。～国。～重。～之有故（立论有根据）。\n(4)对待，处理～身（对待自己）。～盈。～胜。\n(5)扶助支～。撑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-持"},{"id":"glyph-kai-6302","script":"kai","character":"挂","reading":"guà","description":"挂字耳。”\n悬挂;下垂\n⒈悬，悬吊～图片。悬～。彩灯高～。\n⒉牵绊，勾住，惦记牵～。～钩。～怀。～记。\n⒊登记去～号。快～失。\n⒋粘上，附着裤子上～了一层泥。\n⒌量词。用于成串的东西两～葡萄。三～珠子。\n①喜庆日子悬挂彩绸。\n②作战中负伤流血。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挂"},{"id":"glyph-kai-6307","script":"kai","character":"指","reading":"zhǐ","description":"zhǐ：(1)手伸出的支体（脚趾亦作脚指”）手～。巨～（大拇指）。～甲。～纹。～印。屈～可数。\n(2)量词，一个手指的宽度下了三～雨。\n(3)（手指或物体尖端）对着，向着～着。～画。～南针。～手画脚。\n(4)点明，告知～导。～引。～正。～责。～控（指名控告）。～摘。～挥。～日可待。\n(5)直立，竖起令人发（fà）～（形容极为愤怒）。\n(6)意向针对～标。～定。\n(7)古同旨”，意义，目的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-指"},{"id":"glyph-kai-6309","script":"kai","character":"按","reading":"àn","description":"àn：(1)用手或手指压～铃。～键。～钮。～脉。～摩。\n(2)止住～捺。～耐。～压。\n(3)依照～照。～理。～例。～说。～质论价。\n(4)考查，研求～验（审查验证）。～察（稽查审察）。\n(5)（编者、作者等）在正文之外所加的说明或论断～语。编者～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-按"},{"id":"glyph-kai-630e","script":"kai","character":"挎","reading":"kuà；kū","description":"kuà：(1)胳膊弯起来挂着东西她～着篮子上街。\n(2)把东西挂在肩上或挂在腰里～包。～着照相机。\nkū：抠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挎"},{"id":"glyph-kai-6311","script":"kai","character":"挑","reading":"tiāo；tiǎo","description":"tiāo：(1)扁担等两头挂着东西，用肩担着～土。～夫（旧时以给人挑货物行李为业的人）。\n(2)挑的东西～担。\n(3)挖取～荠菜。\n(4)量词，用于成挑儿的东西一～儿白菜。\n(5)选，拣～选。～拣。～剔。～肥拣瘦。\n(6)古同佻”，佻达。\ntiǎo：(1)用竿子棍棒等的一头举起或支起～起帘子。\n(2)用条状物或有尖的东西拨开或弄出来～打。\n(3)拨弄，引动～拨。～动。～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挑"},{"id":"glyph-kai-6316","script":"kai","character":"挖","reading":"wā","description":"wā：(1)掘，掏～掘。～墙脚（喻拆台）。～空心思。\n(2)抓～破了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挖"},{"id":"glyph-kai-631a","script":"kai","character":"挚","reading":"zhì","description":"古国名\n通贽”。见面礼","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挚"},{"id":"glyph-kai-631f","script":"kai","character":"挟","reading":"jiā","description":"挟制\n⒈用胳膊夹住。\n⒉携同～带。\n⒊凭借权势或抓住对方弱点，强迫人服从～制。要～。\n⒋怀着，藏着～怨。～不信之心。\n挟jiā 1.同\"夹\"。夹取;夹住。 2.通\"浃\"。通达;和洽;周遍。 3.通\"梜\"。筷子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挟"},{"id":"glyph-kai-6320","script":"kai","character":"挠","reading":"náo","description":"搅,搅动\n⒈搅，搅动，扰乱～乱。阻～。\n⒉弯曲，屈服贞而不～。百折不～。\n⒊抓，搔～痒。\n挠rào 1.缠绕。 2.船桨。\n挠xiāo 1.见\"挠挑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挠"},{"id":"glyph-kai-6321","script":"kai","character":"挡","reading":"dǎng","description":"遮蔽\n间隙\n用于隔热或隔风或作为装饰的装置\n用于调节机械运行速度及控制方向的装置,排挡”的简称\n某些仪器和测量装置用来表明光、电、热等量的等级\n①拦住；抵挡；遮蔽～风、～太阳。\n②用来遮挡的东西炉～。\n③汽车排挡的简称。又见dàng。\n【挡驾】婉辞。谢绝来客访问。\n【挡箭牌】古代士兵防身的盾牌。比喻推托或掩饰的借口。\n挡tǎng 1.捶打。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挡"},{"id":"glyph-kai-6323","script":"kai","character":"挣","reading":"zhèng；zhēng","description":"zhèng：(1)用力支撑或摆脱～脱。～开。\n(2)出力取得～钱。～饭吃。\nzhēng：〔～扎〕尽力支撑或摆脱，如垂死～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挣"},{"id":"glyph-kai-6324","script":"kai","character":"挤","reading":"jǐ","description":"排斥;排挤\n毁坏;损坏\n⒈用力压使排出～牙膏。～羊奶。\n⒉想法子腾出来～时间。\n⒊拥，推，紧挨拥～。车厢里～满了人。街上也是人～人。〈引〉排斥相互排～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挤"},{"id":"glyph-kai-6325","script":"kai","character":"挥","reading":"huī","description":"舞动;摇动\n挥刀奋斫。\n⒉散出，甩出～金如土。～汗如雨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挥"},{"id":"glyph-kai-6328","script":"kai","character":"挨","reading":"āi；ái","description":"āi：(1)依次，顺次～门逐户。\n(2)靠近～近。肩～着肩。\n打；\nái：(1)遭受～打。～骂。\n(2)拖延～时间。～延。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挨"},{"id":"glyph-kai-632a","script":"kai","character":"挪","reading":"nuó","description":"nuó：(1)移动～动。～移。～借。～用。\n(2)揉搓～挲。～绳破篾（搓绳子，破篾片）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挪"},{"id":"glyph-kai-632b","script":"kai","character":"挫","reading":"cuò","description":"cuò：(1)不顺利，失败～折。～败。～伤。～失。\n(2)按下，使音调降低抑扬顿～。\n(3)摧折。\n(4)书法用笔的一种。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挫"},{"id":"glyph-kai-632f","script":"kai","character":"振","reading":"zhèn","description":"zhèn：(1)搬动，挥动～动。～荡。～幅。～臂。～聋发聩（喻唤醒糊涂麻木的人）。\n(2)奋起，兴起～奋。～作。～兴（xīng）。～～有辞。\n(3)古同赈”，救济。\n(4)古同震”，威震。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-振"},{"id":"glyph-kai-633a","script":"kai","character":"挺","reading":"tǐng","description":"tǐng：(1)笔直，突出笔～。～进。～拔。～立。～秀。～括（guā）（衣服、衣料等平整）。～劲（jìng）。\n(2)伸直，凸出～直。～起腰。\n(3)支撑～节（坚持节操）。\n(4)很～好。～香。\n(5)量词，用于挺直物一～机关枪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挺"},{"id":"glyph-kai-633d","script":"kai","character":"挽","reading":"wǎn","description":"wǎn：(1)拉，牵引～弓。～留。\n(2)设法使局势好转或恢复原状～救。力～狂澜。\n(3)追悼死人～词。～联。～幛。\n(4)古同晚”，后来的。\n(5)同绾”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-挽"},{"id":"glyph-kai-6342","script":"kai","character":"捂","reading":"wǔ","description":"wǔ：(1)严密地遮盖住或封闭起来～住。～盖子（亦喻掩盖矛盾）。\n(2)古同迕”，逆，对面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捂"},{"id":"glyph-kai-6345","script":"kai","character":"捅","reading":"tǒng","description":"tǒng：(1)用棍、棒、刀、枪等戳刺～娄子（引起纠纷，惹祸。亦称捅漏子”）。～马蜂窝（喻惹祸或招惹不好惹的人而引麻烦）。\n(2)碰，触动纸真薄，一～就破。\n(3)揭露把问题全～出来了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捅"},{"id":"glyph-kai-6346","script":"kai","character":"捆","reading":"kǔn","description":"kǔn：(1)把散的东西用绳扎起来～扎。～绑。\n(2)量词，指捆在一起的东西一～铅笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捆"},{"id":"glyph-kai-6349","script":"kai","character":"捉","reading":"zhuō","description":"zhuō：(1)抓，逮～拿。～奸。～贼。～弄。捕～。捕风～影。\n(2)握～笔。～刀（代人作文）。～襟见肘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捉"},{"id":"glyph-kai-634c","script":"kai","character":"捌","reading":"bā","description":"bā：(1)八”的大写。\n(2)古同扒”，破裂，分开。\n(3)古代一种聚拢谷物的没有齿的耙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捌"},{"id":"glyph-kai-634d","script":"kai","character":"捍","reading":"hàn","description":"hàn：(1)保卫，抵御～卫。～御。\n(2)古代射者左臂佩戴的皮制袖套。\n(3)古同悍”，强悍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捍"},{"id":"glyph-kai-634e","script":"kai","character":"捎","reading":"shāo；shào","description":"shāo：(1)顺便给别人带东西～带。～话。～信。\n(2)掠拂风～鲪滴难开幌”。\n(3)芟除拔剑～罗网”。\nshào：(1)稍微向后倒退（多指骡马等）往后～。\n(2)退～色。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捎"},{"id":"glyph-kai-634f","script":"kai","character":"捏","reading":"niē","description":"niē：(1)用拇指和其他手指夹住。\n(2)用手指把软的东西做成一定的形状～饺子。～面人儿。\n(3)假造，虚构～造。～陷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捏"},{"id":"glyph-kai-6350","script":"kai","character":"捐","reading":"juān","description":"juān：(1)舍弃，抛弃～弃。～生。～躯。\n(2)献助～资。～献。～助。募～。\n(3)旧时献钱得官职～官。～纳。\n(4)赋税的一种车～。房～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捐"},{"id":"glyph-kai-6355","script":"kai","character":"捕","reading":"bǔ","description":"bǔ：捉，逮～捉。～获。～杀。巡～。缉～。～风捉影。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捕"},{"id":"glyph-kai-635e","script":"kai","character":"捞","reading":"lāo","description":"用不正当的手段获取\n捉拿\n唠,唠叨\n⒈从液体中取东西～沙。打～沉船。\n⒉使用不正当的手段取得他大～了一把，发了横财。\n捞láo 1.见\"捞什子\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捞"},{"id":"glyph-kai-635f","script":"kai","character":"损","reading":"sǔn","description":"损失;丧失\n⒈减少～去。有～。\n⒉伤害～伤。～害。～人利己。满招～，谦受益。\n⒊丧失～失。～兵折将。\n⒋用刻薄的话挖苦人这话太～人了。\n⒌刻薄狠毒又凶又～。手段真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-损"},{"id":"glyph-kai-6361","script":"kai","character":"捡","reading":"jiǎn","description":"约束\n拾取;取\n清理\n察看;检查\n捡liǎn 1.拱手。 2.通\"敛\"。收敛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捡"},{"id":"glyph-kai-6362","script":"kai","character":"换","reading":"huàn","description":"huàn：(1)给人东西同时从他那里取得别的东西交～。对～。～工。～文。兑～。\n(2)更改，变变～。更（gēng）～。～马（喻撤换担负某项职务的人，含贬义）。～样。～气。～言之（换句话说）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-换"},{"id":"glyph-kai-6363","script":"kai","character":"捣","reading":"dǎo","description":"冲击;攻打\n①用棍、杵之类砸、舂～蒜、～米。\n②捶打～衣服。\n③搅扰～乱。\n【捣鬼】暗中使用诡计。\n【捣毁】砸坏；击垮。\n捣chóu 1.丛集，稠密。参见\"捣蓍\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捣"},{"id":"glyph-kai-6367","script":"kai","character":"捧","reading":"pěng","description":"pěng：(1)两手托着～心（用手捂住胸，喻拙劣的模仿）。～日。～读（敬辞，读别人的文章等）。～腹大笑。\n(2)量词，用手能捧的东西一～红枣。\n(3)奉承或代人吹嘘～场。吹～。～哏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捧"},{"id":"glyph-kai-636e","script":"kai","character":"据","reading":"jù；jv","description":"依靠,凭借\n根据\n⒈占，占有占～。盘～山洞。～为己有。\n⒉靠着，按着～栏杆。左手～膝。〈引〉依靠，凭借～险固守。\n⒊凭依，按照依～。引经～典。～理力争。\n⒋凭证凭～。证～。要收～。有根有～。\n⒍见jū。\n⒉见jū。\n据jǐ 1.搏击;爪持。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-据"},{"id":"glyph-kai-6376","script":"kai","character":"捶","reading":"chuí","description":"chuí：敲打～衣。～鼓。～打。～拓。～挞。～楚（古代的杖刑）。～胸顿足。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捶"},{"id":"glyph-kai-6377","script":"kai","character":"捷","reading":"jié","description":"jié：(1)战胜～音。报～。～报。\n(2)战胜所获献～。\n(3)快，迅速～速。～径（敏捷机巧）。快～。敏～。～足先登。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捷"},{"id":"glyph-kai-637a","script":"kai","character":"捺","reading":"nà","description":"nà：(1)用手按，抑制按～。～手印。\n(2)笔形之一，由上向右斜下。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捺"},{"id":"glyph-kai-637b","script":"kai","character":"捻","reading":"niǎn；niē","description":"niǎn：(1)用手指搓转（zhuàn）～麻绳。\n(2)搓成的条状物灯～儿。\nniē：古同捏”，用拇指和其他手指夹住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-捻"},{"id":"glyph-kai-6380","script":"kai","character":"掀","reading":"xiān","description":"xiān：(1)揭起，打开～开。～涌。～起。～动。\n(2)发动，兴起～风鼓浪（喻煽动情绪，挑起事端）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掀"},{"id":"glyph-kai-6382","script":"kai","character":"掂","reading":"diān","description":"diān：用手托着东西估量轻重～掇。～量（量”读轻声）。～算。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掂"},{"id":"glyph-kai-6388","script":"kai","character":"授","reading":"shòu","description":"shòu：(1)给，与～予。～权。～命。～奖。～旗。～衔。～意。\n(2)教，传给～业。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-授"},{"id":"glyph-kai-6389","script":"kai","character":"掉","reading":"diào","description":"diào：(1)落下～泪。\n(2)减损，消失～色。～价儿。\n(3)遗失，遗漏这一行～了两个字。\n(4)回转（zhuǎn）～头。～转。\n(5)亿，引申为卖弄，耍～文。～俏。～以轻心。～臂而去。\n(6)对换～包。～换。\n(7)落在后面～队。\n(8)用在动词后表示动作完成改～。戒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掉"},{"id":"glyph-kai-638c","script":"kai","character":"掌","reading":"zhǎng","description":"zhǎng：(1)手心，脚心～心。手～。脚～。鼓～。易如反～。\n(2)用巴掌打～嘴。\n(3)把握，主持，主管～管。～权。～勺。～柜。\n(4)鞋底或牲口蹄子底下的东西鞋～。马～儿。\n(5)姓。\n〔～故〕关于历史人物、典章制度等的故事或传说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掌"},{"id":"glyph-kai-638f","script":"kai","character":"掏","reading":"tāo","description":"tāo：(1)挖～一个洞。\n(2)探取～钱。～腰包。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掏"},{"id":"glyph-kai-6390","script":"kai","character":"掐","reading":"qiā","description":"qiā：(1)用指甲按或截断～算。～花。～尖儿。\n(2)割断，截去～头去尾。\n(3)用手的虎口及手指紧紧握住一把～住。\n(4)量词，一只手或两只手指尖相对握着的数量一～儿松枝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掐"},{"id":"glyph-kai-6392","script":"kai","character":"排","reading":"pái；pǎi","description":"pái：(1)除去，推开～出。～斥。～水。～外。～挤。～山倒海。～忧解难。\n(2)摆成行列～列。～队。～字。～印。～笔。～场。\n(3)排成的行列～头。前～。\n(4)军队的编制单位，班”的上一级。\n(5)练习演戏～戏。\n(6)竹或木平摆着编扎成的水上交通工具木～。竹～。～运。\npǎi：〔～子车〕用人力拉运东西的一种车，多用于运货。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-排"},{"id":"glyph-kai-6398","script":"kai","character":"掘","reading":"jué","description":"jué：(1)刨，挖～土。～井。～进。发～。挖～。\n(2)古同崛”，崛起。\n(3)古同倔”，倔强。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掘"},{"id":"glyph-kai-63a0","script":"kai","character":"掠","reading":"lüě；lüè","description":"lüè：(1)夺取～夺。～取。抢～。劫～。\n(2)擦过～视。浮光～影。\n(3)拷打～笞。～治。拷～。\n(4)砍伐～林。\n(5)顺手抓取随手～起一根棍子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掠"},{"id":"glyph-kai-63a2","script":"kai","character":"探","reading":"tàn","description":"tàn：(1)寻求～求。～讨。～索。～试。勘～。试～。钻～。～幽访胜。～本穷源。\n(2)侦察打听～问。～听。～询。～查。～察。\n(3)做侦察工作的人～马（侦察骑兵）。敌～。密～。\n(4)访问，看望～望。～亲。～监。\n(5)头或上体伸出，手伸入～身。～头～脑。～囊取物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-探"},{"id":"glyph-kai-63a5","script":"kai","character":"接","reading":"jiē","description":"jiē：(1)连成一体～合。～骨。～壤。衔～。\n(2)继续，连续～力。～替。～班。～二连三。再～再厉。\n(3)靠近，挨上～近。邻～。～吻。\n(4)承受，收取～受。～收。～纳。～管。\n(5)迎～风。～生。～待。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-接"},{"id":"glyph-kai-63a7","script":"kai","character":"控","reading":"kòng","description":"kòng：(1)告状，指出罪恶～告。～诉。指～。被～。\n(2)节制，驾驭～制。遥～。\n(3)开弓弓不再～。\n(4)投～于地。\n(5)人的头部朝下或使让残液流出容器的口朝下～净。～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-控"},{"id":"glyph-kai-63a8","script":"kai","character":"推","reading":"tuī","description":"tuī：(1)手抵物体向外或向前用力使物移动～车。～搡。～拿。～倒。～敲。顺水～舟。\n(2)使用工具向前移动进行工作～头。～土。\n(3)使事情开展～广。～行（xíng）。～动。～销。\n(4)进一步想，由已知之点想到其它～及。～究。～导。～论。～测。～事。\n(5)往后挪动（时间上）～延。～移。\n(6)辞让，脱卸～让。～却。～委。～辞。\n(7)举荐，指出某人优点～许。～重（zhòng）。～举。～崇。\n(8)让出，献出～恩。～心置腹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-推"},{"id":"glyph-kai-63a9","script":"kai","character":"掩","reading":"yǎn","description":"yǎn：(1)遮蔽，遮盖～护。～体。～饰。～映。～盖。～蔽。～埋。～人耳目。瑕不～瑜。藏瑕～疵。\n(2)关，合～闭。～门。～卷。\n(3)门、窗、箱柜等关合时夹住了东西～了手。\n(4)乘人不备而袭击或捉拿～杀。～击。～袭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掩"},{"id":"glyph-kai-63aa","script":"kai","character":"措","reading":"cuò","description":"cuò：(1)安放，安排～手。～辞。～置。～身。\n(2)筹划办理～施。～办。筹～。举～失当。\n(3)弃置刑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-措"},{"id":"glyph-kai-63b0","script":"kai","character":"掰","reading":"bāi","description":"bāi：(1)用手把东西分开或折断把烧饼～成两半。\n(2)方言，指情谊破裂，决裂我们早就～了。\n(3)方言，指分析、辨别道理我把这些问题都跟他～通了。～扯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掰"},{"id":"glyph-kai-63b7","script":"kai","character":"掷","reading":"zhì","description":"投射\n腾跃,将自身抛入空中","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掷"},{"id":"glyph-kai-63ba","script":"kai","character":"掺","reading":"chān","description":"同参”。古时候的一种鼓曲名。也指击鼓三次\n细小\n同扦”。女手纤美的样子\n掺shǎn 1.执，操。 2.操守。\n掺shān 1.女手纤美貌。\n掺sēn 1.树木众盛貌。\n掺càn 1.古代鼓曲名。 2.指古代乐曲演奏中的一种击鼓之法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-掺"},{"id":"glyph-kai-63c9","script":"kai","character":"揉","reading":"róu","description":"róu：(1)用手来回擦或搓～擦。～搓。～眼睛。\n(2)团弄～面。～泥球。\n(3)使木弯曲～轮（使木弯曲制作车轮）。～木为耒”。\n(4)古同柔”，使降顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揉"},{"id":"glyph-kai-63cd","script":"kai","character":"揍","reading":"zòu","description":"zòu：(1)打～他。\n(2)打碎小心别把碗～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揍"},{"id":"glyph-kai-63cf","script":"kai","character":"描","reading":"miáo","description":"miáo：依照原样摹画或重复地画～写。～叙。～述。～红。～画。～状。～摹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-描"},{"id":"glyph-kai-63d0","script":"kai","character":"提","reading":"tí；dī；dǐ","description":"tí：(1)垂手拿着有环、柄或绳套的东西～壶。～灯。～篮。～包。～盒。～纲挈领。\n(2)引领（向上或向前等）～心吊胆。～升。～挈。～携。\n(3)说起，举出～起。～出。～醒。～倡。～议。～名。～案。～要。\n(4)将犯人从关押之处带出来～审。～犯人。\n(5)率领，调遣～兵。\n(6)取出～取。～货。\n(7)汉字笔形之一，即挑。\n(8)舀取油、酒等液体的一种用具油～。酒～。\n(9)古代鼓名师帅执～”。\n(10)姓。\n降；\ndī：〔～防〕小心防备。\n降；\ndǐ：投掷荆轲废，乃引其匕首～秦王”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-提"},{"id":"glyph-kai-63d2","script":"kai","character":"插","reading":"chā","description":"chā：(1)扎进去，把细长或薄的东西放进去～入。～秧。～花。～座。～头。～翅难飞。\n(2)加入，参与～班。～话。～曲。～图。～页。～叙。安～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-插"},{"id":"glyph-kai-63e1","script":"kai","character":"握","reading":"wò","description":"wò：(1)手指弯曲合拢，执持～手。～拳。～别。把～。掌～。～力。～笔。～管。～瑜（喻怀有美好的才德）。\n(2)量词，指一把大小或分量一～粗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-握"},{"id":"glyph-kai-63e3","script":"kai","character":"揣","reading":"chuāi；chuǎi；chuài；tuán；zhuī","description":"chuǎi：(1)估量，忖度～测。～摩。～度（duó）。～想。～情（忖度情理）。不～冒昧。\n(2)姓。\nchuài：〔挣（zhèng）～〕见挣1”。\n〔囊（nāng）～〕见囊1”。\nchuāi：放在衣服里～着手。～在怀里。\ntuán：古同团”，聚集的样子。\nzhuī：捶击～而锐之，不可长保”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揣"},{"id":"glyph-kai-63e9","script":"kai","character":"揩","reading":"kāi","description":"kāi：擦，抹～背。～油。～鼻涕。～眼泪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揩"},{"id":"glyph-kai-63ea","script":"kai","character":"揪","reading":"jiū","description":"jiū：用手抓住或扭住～住。～心。～辫子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揪"},{"id":"glyph-kai-63ed","script":"kai","character":"揭","reading":"jiē；qì","description":"jiē：(1)把盖在上面的东西拿起，或把粘合着的东西分开～锅。～幕。\n(2)使隐瞒的事物显露～露。～发。～底。～穿。～短。～晓。\n(3)高举～竿而起。\n(4)标示～橥（zhū）（本是作标记的小木桩，引申为标志。亦作揭著”）。～示。\n(5)扛，持。\n(6)姓。\n掀；\n捂；盖；\nqì：提起衣裳～衣涉水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揭"},{"id":"glyph-kai-63f4","script":"kai","character":"援","reading":"yuán","description":"yuán：(1)牵引攀～。～之以手。\n(2)帮助，救助支～。～外。～助。～军。～救。增～。孤立无～。\n(3)引用～用。～引。～据。\n(4)执，持～笔（拿起笔来写，如～～而书”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-援"},{"id":"glyph-kai-63fd","script":"kai","character":"揽","reading":"lǎn","description":"搂,拥抱,围抱\n采摘\n招惹\n⒈把持独～大权。\n⒉招来，拉过来～生意。个人包～。\n⒊捆，搂抱～木柴。母亲～着婴孩睡觉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-揽"},{"id":"glyph-kai-6400","script":"kai","character":"搀","reading":"chān","description":"混杂;搀和\n①搀扶让我～你一把。\n②把一种东西混入另一种东西里～沙子、～假。\n【掺兑】把成分不同的东西混合在一起把白面和玉米面～在一起蒸丝糕。\n⒈挽，牵扶～扶。手～手。～着老大娘走人行道。\n⒉混合～杂。～点糖。不能～沙子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搀"},{"id":"glyph-kai-6401","script":"kai","character":"搁","reading":"gē","description":"停顿;耽搁\n经受,承受\n再结实的身子骨儿,搁得住这么折腾吗?\n搁gē放，置把书～好。汤要～盐。〈引〉停顿，不做此事～几天再说。\n搁gé承受，禁受心里～不住气。轿车里～不下东西了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搁"},{"id":"glyph-kai-6402","script":"kai","character":"搂","reading":"lǒu","description":"搂抱;用手或工具把东西向自己面前聚集\n兜揽\n核算\n用手拢着提\n⒈将东西聚拢起来～草。～柴。\n⒉搜刮贪官污吏专会～钱。\n⒊用手指往怀里拨、扳～手枪。～机枪。\n⒈两臂合抱，向怀里拢着～抱。～着孩子。\n⒉量词三～草。两～粗的银杏树。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搂"},{"id":"glyph-kai-6405","script":"kai","character":"搅","reading":"jiǎo","description":"混合;拌合;搅拌\n胡闹;嬉戏\n⒈扰乱，打扰莫～乱。别～扰。\n⒉拌和～拌。～匀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搅"},{"id":"glyph-kai-640f","script":"kai","character":"搏","reading":"bó","description":"bó：(1)对打～斗。～击（奋力进击）。～战。～膺（捶胸，表示愤怒）。肉～。拼～。\n(2)跳动～动。脉～。\n(3)捕捉～噬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搏"},{"id":"glyph-kai-6413","script":"kai","character":"搓","reading":"cuō","description":"cuō：两个手掌相对或一个手掌放在别的东西上擦揉～。～弄。～洗。～澡。～手。～绳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搓"},{"id":"glyph-kai-6414","script":"kai","character":"搔","reading":"sāo","description":"sāo：(1)挠，用手指甲轻刮～痒。～头。隔靴～痒。\n(2)古同骚”，扰乱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搔"},{"id":"glyph-kai-641c","script":"kai","character":"搜","reading":"sōu","description":"sōu：(1)寻求，寻找～集。～寻。～求。～讨。～罗。～刮。～索枯肠。\n(2)检查～查。～身。～腰。～捕。～索。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搜"},{"id":"glyph-kai-641e","script":"kai","character":"搞","reading":"gǎo","description":"gǎo：做，弄，干，办～好。～通。～鬼。～小动作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搞"},{"id":"glyph-kai-642c","script":"kai","character":"搬","reading":"bān","description":"bān：(1)移动，迁移～动。～移。～迁。～运。生～硬套。\n(2)挑拨离间～唆（调唆）。～弄是非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搬"},{"id":"glyph-kai-642d","script":"kai","character":"搭","reading":"dā","description":"dā：(1)支；架设；用棍棒等东西交接捆扎起来～建。～盖。～制。～桥。～救。～架子。\n(2)共同抬把桌子～起来。\n(3)交接，配合～配。～伙。～档。～售。～伴。～帮。～腔。～话。～界。～讪。\n(4)乘车船等～车。～船。～客。～载。\n(5)方言，指处、地方这～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-搭"},{"id":"glyph-kai-643a","script":"kai","character":"携","reading":"xié","description":"xié：(1)带～手。～带。扶老～幼。\n(2)离，叛离～离。～贰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-携"},{"id":"glyph-kai-6444","script":"kai","character":"摄","reading":"shè","description":"执;持\n拘捕\n辅助、佐助\n摄,佐也。╠\n⒉代理，辅助～政。～位。\n⒊保养～生。珍～。\n⒋撩起，整理～帘。～衣。\n⒌收敛～绳。\n摄niè 1.安定。\n摄shà 1.古代祭祀之位，形似腰扇。参见\"屏摄\"。\n摄zhé 1.折叠。 2.见\"摄叶\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摄"},{"id":"glyph-kai-6446","script":"kai","character":"摆","reading":"bǎi","description":"排列;放置\n挥手,左右摇动手\n来回或上下地摇动\n①安排；布置把书～到书架上。\n②显示；炫耀～威风。\n③摇动；亿摇～不定。\n④悬在细线上能做往复运动的重锤的装置。\n⑤钟表或其他精密仪器上用来控制摆动频率的机械装置。\n⑥长袍、上衣、衬衫等的最下面的部分。又叫下摆。\n【摆动数列】一个实数列从第二项起，有些项大于它的前一项，有些项却小于它的前一项。这样的实数列叫做摆动数列。\n【摆门面】讲究排场，装饰外表。\n【摆平】\n①公平对待。将人打伤；被打伤。\n【摆线】一个动圆沿着一条定直线作纯滚动时，动圆圆周上一点所画出的平面曲线叫摆线或旋轮线。摆线又叫最速下降线，这是因为质点在重力作用下从一点滚到另一点时，沿摆线的路径所花时间最短。\n【摆夷】见【傣族】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摆"},{"id":"glyph-kai-6447","script":"kai","character":"摇","reading":"yáo","description":"yáo：(1)摆动～曳。～晃。～荡。～篮。动～。～摆。～头摆尾。～～欲坠。扶～直上。\n(2)往上升风举云～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摇"},{"id":"glyph-kai-644a","script":"kai","character":"摊","reading":"tān","description":"摊派\n把糊状食物倒在锅中使成为薄片\n摊 〈名〉\n摊子\n古代\n⒈展开，摆开～开。把意见～出来。\n⒉将糊状物放在热锅里铺成薄片煎熟～饼。～鸡蛋。\n⒊分派，分担～派。分～。\n⒋路旁或街旁摆的售货处书～。地～子。菜～儿。水果～。\n⒌凝集成一片一～水。一～稀泥。\n⒍遇到，碰上他～上了好事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摊"},{"id":"glyph-kai-6454","script":"kai","character":"摔","reading":"shuāi","description":"shuāi：(1)用力往下扔把帽子～在床上。～打。\n(2)很快地掉下别～下来。\n(3)因掉下而破坏把碗～碎了。\n(4)跌跤～倒。～跤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摔"},{"id":"glyph-kai-6458","script":"kai","character":"摘","reading":"zhāi","description":"zhāi：(1)采取，拿下采～。～取。～桃子。～除。\n(2)选取～要。～录。～编。文～。～引。寻章～句。指～（挑出缺点）。\n(3)借～兑。东～西借。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摘"},{"id":"glyph-kai-6467","script":"kai","character":"摧","reading":"cuī","description":"cuī：(1)破坏，折断～残。～折。～颓。～眉折腰。\n(2)挫败，挫折～败。～挫。～陷。\n(3)伤痛～怆。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摧"},{"id":"glyph-kai-6469","script":"kai","character":"摩","reading":"mó；mā","description":"mó：(1)擦，蹭，接触～擦。～天。～崖（山崖上刻的文字、佛像等）。～肩接踵。～顶放踵。\n(2)摸，抚～弄。～挲（suō）\n(3)研究，切磋观～。揣～（a.研究，仔细琢磨；b.估量，推测）。\n(4)古同磨”，磨擦。\nmā：〔～挲（sɑ）〕用手轻轻按着一下一下地移动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摩"},{"id":"glyph-kai-6478","script":"kai","character":"摸","reading":"mō","description":"mō：(1)用手接触或轻轻抚摩～他的头。\n(2)用手探取、寻找～鱼捞虾。\n(3)揣测，试探～底。～索。\n(4)暗中行进，在认不清的道路上行走～哨。～黑儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摸"},{"id":"glyph-kai-6479","script":"kai","character":"摹","reading":"mó","description":"mó：仿效，照着样子做～仿（亦作模仿”）。～刻。～拟（亦作模拟”）。～写（亦作模写”）。～状。～印。临～。描～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-摹"},{"id":"glyph-kai-6487","script":"kai","character":"撇","reading":"piě；piē","description":"piē：(1)丢开，抛弃～开。～弃。\n(2)由液体表面舀染粥时把沫儿～掉。\npiě：(1)平着向前扔～手榴弹。\n(2)汉字笔形之一，由上向左而斜下。\n(3)像汉字的撇形的～嘴。两～黑眉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撇"},{"id":"glyph-kai-6491","script":"kai","character":"撑","reading":"chēng","description":"chēng：(1)支着，支持～竿跳。支～。～持（勉强支持）。～腰（喻给予有力支持）。～拒。～门面。\n(2)用篙使船前进～船。\n(3)使张开～伞。～口袋。\n(4)使保持张开状态的器物～子。～圈（quān）。\n(5)饱胀到容不下的程度吃～着了。口袋～破了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撑"},{"id":"glyph-kai-6492","script":"kai","character":"撒","reading":"sā；sǎ","description":"sā：(1)放开，发出～手。～网。～谎（说谎）。～气。\n(2)尽量施展或表现出来～刁。～奸。～娇。～欢儿。～野。～酒疯。\n(3)姓。\n洒；\nsǎ：(1)散播，散布，散落～种（zhǒng）。～播。把酒端平，别～了。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撒"},{"id":"glyph-kai-6495","script":"kai","character":"撕","reading":"sī","description":"sī：用手把东西扯裂～开。～破。～碎。～扯。～毁。～票（绑票的匪徒因勒索金钱的要求没得到满足而把掳去的人杀死）。～心裂肺（形容极度悲伤）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撕"},{"id":"glyph-kai-649e","script":"kai","character":"撞","reading":"zhuàng","description":"zhuàng：(1)冲打，碰击～钟。～车。～击。顶～。冲～。\n(2)碰见，无意中遇到～见。\n(3)试探～大运（碰运气）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撞"},{"id":"glyph-kai-64a4","script":"kai","character":"撤","reading":"chè","description":"chè：(1)免除，除去～职。～销。～任。\n(2)退，收回～退。～防。～岗。～回。～诉。～换。～离。\n(3)减轻，减退～味儿。～分量。～火。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撤"},{"id":"glyph-kai-64a9","script":"kai","character":"撩","reading":"liáo；liāo","description":"liāo：(1)掀起～起衣襟。～起头发。\n(2)用手舀着洒水先～水后扫地。\nliáo：挑弄，引逗～拨。～乱（纷乱，如眼花～～”。亦作缭乱”）。春色～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撩"},{"id":"glyph-kai-64ac","script":"kai","character":"撬","reading":"qiào","description":"qiào：用杠棒或尖利的工具借助支点拨动或挑（tiǎo）起东西把瓶盖～开。溜门～锁。把这块大石头～下来运走。～杠（亦称撬棍”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撬"},{"id":"glyph-kai-64ad","script":"kai","character":"播","reading":"bō","description":"bō：(1)撒种～种（zhǒng）。～种（zhòng）（用撒布种子的方式种植）。～撒。夏～。春～。\n(2)传扬，传布广～。传～。～音。～发。～弄。～扬（a.宣扬，传扬；b.发动）。～放。～映。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-播"},{"id":"glyph-kai-64ae","script":"kai","character":"撮","reading":"cuō；zuǒ","description":"cuō：(1)聚起，多指用簸箕状的器具铲起东西～成一堆。～土。～合。\n(2)取，摘取～要。\n(3)用手指捏取细碎的东西～药。\n(4)中国市制容量单位，一升的千分之一。\n(5)量词一～米。\n(6)撮东西用的器具～子。～箕。\nzuǒ：量词，用于成丛的毛发剪下一～头发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撮"},{"id":"glyph-kai-64b0","script":"kai","character":"撰","reading":"zhuàn","description":"zhuàn：(1)才能异乎三子者之～”。\n(2)写作，著书～著。～述。～写。～文。～稿。～次（编辑、排列）。～序（撰写叙述）。～录。～集。杜～（臆造，没有根据地编造）。\n(3)持，拿着～余辔兮高驼翔”。\n(4)指天地阴阳等自然现象的变化规律。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撰"},{"id":"glyph-kai-64b5","script":"kai","character":"撵","reading":"niǎn","description":"c出\n因不付租金被撵出\n好像要把她撵出屋子似的\n如果你不能自爱,我就要把\n⒈驱逐，赶走～出去。～走他。\n⒉追赶快，～上。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撵"},{"id":"glyph-kai-64bc","script":"kai","character":"撼","reading":"hàn","description":"hàn：(1)搬动～顿（搬动颠仆）。～天动地。蚍蜉～大树，可笑不自量”。\n(2)用言语打动人微言～之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-撼"},{"id":"glyph-kai-64c2","script":"kai","character":"擂","reading":"lèi；léi","description":"léi：(1)研磨～成细末。\n(2)打～鼓。自吹自～。\nlèi：〔～台〕比武所搭的台子，如摆～～”。打～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擂"},{"id":"glyph-kai-64c5","script":"kai","character":"擅","reading":"shàn","description":"shàn：(1)超越职权，自作主张～专。～自。～行（xíng）。～断（专行）。专～独行。～离职守。\n(2)独揽，占有～权。～利。～兵（拥有兵权）。～国。～美。\n(3)长（cháng）于，善于～长（cháng）。不～辞令。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擅"},{"id":"glyph-kai-64cd","script":"kai","character":"操","reading":"cāo","description":"cāo：(1)拿，抓在手里～刀。～觚（手持木简，指写诗作文）。～管（执笔，指写作）。～刀必割（喻不失时机，要当机立断）。\n(2)控制、掌握～舟。～纵。\n(3)从事～心。～办。～作。～持。～劳。～之过急。\n(4)体力的锻炼，军事的训练～练。～场。～演。上～。\n(5)用某种语言或方言讲话他～一口闽南音。\n(6)行为，品行～行。～守。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-操"},{"id":"glyph-kai-64ce","script":"kai","character":"擎","reading":"qíng","description":"qíng：向上托；举～受。～天柱（喻担负重任的人）。众～易举。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擎"},{"id":"glyph-kai-64d2","script":"kai","character":"擒","reading":"qín","description":"qín：捉拿～拿。生～。就～。欲～故纵。～贼先～王。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擒"},{"id":"glyph-kai-64e6","script":"kai","character":"擦","reading":"cā","description":"cā：(1)揩拭～脸。～洗。～桌子。\n(2)搽，涂敷～粉。～油。\n(3)摩，搓摩拳～掌。～澡。\n(4)贴近～黑（傍晚）。～边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-擦"},{"id":"glyph-kai-6500","script":"kai","character":"攀","reading":"pān","description":"pān：(1)抓住东西向上爬～登。～高。～越。～桂（古代指科举考试登第）。～折（zhé）。～附。～援。\n(2)拉扯，拉拢，结交～交。～扯。～谈。～亲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攀"},{"id":"glyph-kai-652f","script":"kai","character":"支","reading":"zhī","description":"zhī：(1)撑持，伸出，竖起～撑。～援。体力不～。\n(2)受得住乐不可～。\n(3)领款或付款～付。\n(4)调度，指使～使。～应。～着儿。\n(5)附属于总体的一个部分总～。～流。～离。\n(6)量词一～笔。\n〔地～〕历法中用的十二个字子丑寅卯辰巳午未申酉戌亥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-支"},{"id":"glyph-kai-6536","script":"kai","character":"收","reading":"shōu","description":"shōu：(1)接到，接受～发。～信。～支。～讫。～益。\n(2)藏或放置妥当这是重要东西，要～好了。\n(3)割断成熟的农作物～割。～成。麦～。\n(4)招回～兵。～港。\n(5)聚，合拢～容。～理。～集。\n(6)结束～尾。～煞。～盘。\n(7)逮捕，拘押～捕。～监。～押。～审。\n(8)约束，控制（感情或行动）～束。～心。～伏（亦作收服”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-收"},{"id":"glyph-kai-6539","script":"kai","character":"改","reading":"gǎi","description":"gǎi：(1)变更，更换～变。更（gēng）～。～革。～造。～善。～弦更张。朝令夕～。～编。～写。纂～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-改"},{"id":"glyph-kai-653b","script":"kai","character":"攻","reading":"gōng","description":"gōng：(1)打击，与守”相对～击。～占。～取。～心。～关。～陷。\n(2)指责，驳斥～难（nàn）。群起而～之。\n(3)治病以毒～毒。\n(4)致力学习或研究～读。～书。专～医学。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-攻"},{"id":"glyph-kai-653e","script":"kai","character":"放","reading":"fàng","description":"fàng：(1)解脱约束，得到自由把笼子里的鸟～了。～胆。～诞。～任。～肆。～歌。～怀±～。释～。\n(2)散（sàn）～工。～假。～学。～晴（阴雨后转晴）。\n(3)带牲畜到野外去吃草～牧。～羊（亦喻任其自由行动，放手不管，含贬义）。\n(4)驱逐到远方去～逐。～黜。流～。\n(5)到基层去～官（古时指任命为外地官员）。下～。\n(6)发出～电。～毒。～光。发～。\n(7)借钱给别人，收取利息～债。～贷。\n(8)扩展～大。～宽。\n(9)花开百花齐～。心花怒～。\n(10)搁、置这件事情不要紧，先～一～。存～。～弃。～心。～置。\n(11)至～乎四海。摩顶～踵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-放"},{"id":"glyph-kai-653f","script":"kai","character":"政","reading":"zhèng","description":"zhèng：(1)治理国家事务～治。～府。～党。～权。～纲。～策。～令。～绩。～见。～客（为个人或某一集团利益从事政治活动的人）。～局。～变。参～。议～。\n(2)国家某一部门主管的业务财～。邮～。民～。\n(3)家庭或集体生活中的事务家～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-政"},{"id":"glyph-kai-6545","script":"kai","character":"故","reading":"gù","description":"gù：(1)意外的事情事～。变～。～障。\n(2)原因缘～。原～。\n(3)有心，存心～意。～杀（有意谋杀）。明知～犯。\n(4)老，旧，过去的，原来的～事（a.旧事，成例；b.有连贯性的比较完整的事情，比较适合于口头讲述，事”读轻声）。～人。～乡。～土（故乡）。～园（故乡）。～居。～国（故乡，亦指祖国）。～纸堆（泛指旧而多的文籍）。革～鼎新（革”，除去；鼎”，更新；破除旧的，建立新的）。～步自封（故步”，原来的步子；封”，限制；喻安于现状，不求进取。亦作固步自封”）。\n(5)朋友，友情亲～。沾亲带～。\n(6)死亡（指人）～去。病～。\n(7)所以，因此～此。～而。\n(8)古同顾”，反而。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-故"},{"id":"glyph-kai-6548","script":"kai","character":"效","reading":"xiào","description":"xiào：(1)摹仿～法。仿～。上行下～。～尤（明知别人的行为是错的而照样去做）。\n(2)功用，成果～验。～果。成～。有～。功～。～益。～用。～应。～率（lǜ）。\n(3)尽、致～力。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-效"},{"id":"glyph-kai-654c","script":"kai","character":"敌","reading":"dí","description":"抵抗;抵挡\n攻击\n①仇敌～人、抗～。\n②对抗；抵拒所向无～。\n③同等；相当势均力～。\n【敌敌畏】〈外〉一种有机磷杀虫剂，为稍带芳香臭体的无色透明液体。\n【敌酋】敌人的头子。\n【敌人】敌对的人或敌对的方面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敌"},{"id":"glyph-kai-654f","script":"kai","character":"敏","reading":"mǐn","description":"mǐn：(1)迅速，灵活～捷。～感。～锐。～达（敏捷而通达事理）。灵～。聪～。神经过～。\n(2)奋勉～求（勉力以求）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敏"},{"id":"glyph-kai-6551","script":"kai","character":"救","reading":"jiù","description":"jiù：(1)给予帮助使脱离危险或解脱困难～济。～命。～护。～国。～难（nàn）。～灾。～药。～正（补救匡正）。～死扶伤。～困扶危。\n(2)终止濯以～热。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-救"},{"id":"glyph-kai-6559","script":"kai","character":"教","reading":"jiāo；jiào","description":"jiāo：把知识或技能传授给人。jiào：教育、教导；宗教，如教学、教诲、佛教。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-655b","script":"kai","character":"敛","reading":"liǎn","description":"收获\n征收\n豹因重敛百姓\n⒈收，聚集收～。聚～。秋～冬藏。〈引〉征收横征暴～。\n⒉约束，检点～迹。闭门自～。\n敛lián 1.见\"敛盂\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敛"},{"id":"glyph-kai-655e","script":"kai","character":"敞","reading":"chǎng","description":"chǎng：(1)（房屋、庭院等）没有遮蔽～亮。宽～。\n(2)张开，打开～着大门。～篷马车。～开供应。\n(3)古同畅”，畅快。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敞"},{"id":"glyph-kai-6562","script":"kai","character":"敢","reading":"gǎn","description":"gǎn：(1)有勇气，有胆量勇～。果～。～闯。～死队。～作～为。～怒而不～言。\n(2)谦辞，不敢”的简称，冒昧的意思～问。～请。～烦。\n(3)方言，莫非～许。～怕。～是哥哥回来了？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敢"},{"id":"glyph-kai-6563","script":"kai","character":"散","reading":"sàn；sǎn","description":"sàn：(1)分开，由聚集而分离分～。解～。涣～。～落。～失。～逸。\n(2)分布，分给～布。～发（fā）。天女～花。\n(3)排遣～心。～闷（mèn）。\n(4)解雇他干的不好，让那家饭店给～了。\n集；聚；\nsǎn：(1)没有约束，松开松～。～漫。懒～。～曲。～记。～板。～文。披～头发。\n(2)分开的，分离的～居。～乱。～座。～兵游勇。\n(3)零碎的～碎。～装。～页。\n(4)中医称药末～剂。丸～膏丹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-散"},{"id":"glyph-kai-6566","script":"kai","character":"敦","reading":"dūn；duì","description":"dūn：(1)厚道，笃厚～朴。～厚。～实。\n(2)诚心诚意～聘。～请。\n(3)督促使虞～匠”。～劝。～促。\n(4)姓。\nduì：古代盛黍稷的器具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敦"},{"id":"glyph-kai-656c","script":"kai","character":"敬","reading":"jìng","description":"jìng：(1)尊重，有礼貌地对待尊～。致～。～重（zhòng）。～爱。～仰。恭～。～辞。～慕。～献。\n(2)表示敬意的礼物喜～。寿～。\n(3)有礼貌地送上去～酒。～香。\n(4)谨慎，不怠慢慎始～终（自始自终都谨慎不懈）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敬"},{"id":"glyph-kai-6570","script":"kai","character":"数","reading":"shù；shǔ；shuò","description":"shù：数目、数量；几，几个。shǔ：计算数目；列举、责备。shuò：屡次，如数见不鲜。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-6572","script":"kai","character":"敲","reading":"qiāo","description":"qiāo：打，击～打。～击。～诈。～边鼓（喻从旁帮人说话）。～门砖。～骨吸髓。旁～侧击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敲"},{"id":"glyph-kai-6574","script":"kai","character":"整","reading":"zhěng","description":"zhěng：(1)有秩序，不乱～齐。～洁。～然有序。\n(2)治理～治。～改。～编。～饬（ａ．使有条理，整顿；ｂ．整齐，有条理）。～装待发。\n(3)修理，修饰～形。～旧如新。\n(4)完全无缺，没有零头～体。完～。\n(5)使人吃苦头～人。\n(6)搞，弄咋～的？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-整"},{"id":"glyph-kai-6577","script":"kai","character":"敷","reading":"fū","description":"fū：(1)布置，铺开，摆开～设。～陈（铺陈，详细叙述）。～衍（ａ．叙述并发挥，亦作敷演”；ｂ．做事不够负责或待人不恳切，只做表面上的应付；ｃ．勉强维持）。\n(2)涂上，搽上～药。～粉。\n(3)足够入不～出。\n(4)古同肤”，表面的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-敷"},{"id":"glyph-kai-6587","script":"kai","character":"文","reading":"wén","description":"wén：(1)事物错综所造成的纹理或形象灿若～锦。\n(2)刺画花纹～身。\n(3)记录语言的符号～字。～盲。以～害辞。\n(4)用文字记下来以及与之有关的～凭。～艺。～体。～典。～苑。～献（指有历史价值和参考价值的图书资料）。～采（ａ．文辞、文艺方面的才华；ｂ．错杂艳丽的色彩）。\n(5)人类劳动成果的总结～化。～物。\n(6)自然界的某些现象天～。水～。\n(7)旧时指礼节仪式虚～。繁～缛节（过多的礼节仪式）。\n(8)文华辞采，与质”、情”相对～质彬彬。\n(9)温和～火。～静。～雅。\n(10)指非军事的～职。～治武功（指礼乐教化和军事功绩）。\n(11)指以古汉语为基础的书面语～言。～白间杂。\n(12)专指社会科学～科。\n(13)掩饰～过饰非。\n(14)量词，指旧时小铜钱一～不名。\n(15)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-文"},{"id":"glyph-kai-658b","script":"kai","character":"斋","reading":"zhāi","description":"遂许斋五日\n秦王斋五日。\n进食\n⒈迷信者祭祀前整洁身心～祭。～戒沐浴。〈引〉信奉佛教、道教等人吃的素食吃～。\n⒉施舍饭食给僧人～僧。\n⒊书房或学舍或某些商店名称书～。东～。荣宝～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斋"},{"id":"glyph-kai-658c","script":"kai","character":"斌","reading":"bīn","description":"bīn：〔～～〕同彬彬”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斌"},{"id":"glyph-kai-6591","script":"kai","character":"斑","reading":"bān","description":"bān：一种颜色中夹杂的别种颜色的点子或条纹～点。～纹。～斓。雀～。～秃。～白。～竹。～驳（色彩错落）。管中窥豹，可见一～（喻从看到的一部分，推测全貌）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斑"},{"id":"glyph-kai-6597","script":"kai","character":"斗","reading":"dòu；dǒu","description":"dǒu：(1)中国市制容量单位（十升为一斗，十斗为一石）～酒只鸡（经常用作招待客人的简单酒食，家常便饭）。\n(2)量粮食的器具～筲之人（形容人器量狭小，见识短浅）。\n(3)形容小东西的大～胆。\n(4)形容大东西的小～室。\n(5)像斗的东西～车。～笠。～篷。熨～。\n(6)星名，二十八宿之一，亦泛指星南～。气冲～牛（怒气冲天）。\n(7)特指北斗星”～折蛇行。\n(8)古同陡”，高耸的样子。\n(9)古同陡”，突然。\n〔斗拱〕（枓栱）拱是建筑上弧形承重结构，斗是垫拱的方木块，合称斗拱。\n（魕）\ndòu：(1)对打～殴。战～。\n(2)比赛胜负，争胜～力。～劲。～智。～志昂扬。\n(3)使动物之间互争高下～牛。～蟋蟀。\n(4)拼合，对准，凑近～眼。\n(5)古同逗”，逗引。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斗"},{"id":"glyph-kai-6599","script":"kai","character":"料","reading":"liào","description":"liào：(1)估计，猜想～想。预～。\n(2)可供制造其他东西的物质材～。～子。备～。\n(3)喂牲口用的谷物草～。\n(4)一种熔点较低的玻璃，用来制造器皿或工艺品～器。\n(5)烹调时的调味品调～。\n(6)整理，处理～理。\n(7)量词，用于中药配制丸药，处方剂量的全份配一～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-料"},{"id":"glyph-kai-659c","script":"kai","character":"斜","reading":"xié","description":"xié：不正，跟平面或直线既不平行也不垂直的～坡。～面。～度。～线。～视。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斜"},{"id":"glyph-kai-659f","script":"kai","character":"斟","reading":"zhēn","description":"zhēn：(1)往杯盏里倒饮料～茶。～酒。\n(2)古代指精羹汁厨人进～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斟"},{"id":"glyph-kai-65a4","script":"kai","character":"斤","reading":"jīn","description":"jīn：(1)中国市制重量单位二～。～～（过分计较琐细的或无关紧要的事物，如～～计较”）。\n(2)古代砍伐树木的工具斧～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斤"},{"id":"glyph-kai-65a5","script":"kai","character":"斥","reading":"chì","description":"chì：(1)责备～责。怒～。驳～。训～。\n(2)指，指出～谬（指出错误）。\n(3)使退去，使离开～退。\n(4)开拓开地～境。\n(5)多，广充～。\n(6)侦察，伺望～候（旧时侦察敌情的士兵）。\n(7)盐碱地～卤。\n(8)古同尺”，尺蠖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斥"},{"id":"glyph-kai-65a7","script":"kai","character":"斧","reading":"fǔ","description":"fǔ：(1)砍东西用的工具，多用来砍木头。古代亦用来作兵器～子。～头。～钺。～柯（ａ．斧子的柄；ｂ．喻政权、权柄）。\n(2)用斧砍～正（敬辞，请人修正文句，亦作斧政”）。～凿（ａ．斧子或凿子；ｂ．指文艺作品等矫揉造作）。～藻（雕饰、修饰）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斧"},{"id":"glyph-kai-65a9","script":"kai","character":"斩","reading":"zhǎn","description":"失期当斩。\n借第令毋斩。\n斩zhǎn砍，杀～首。～草除根。～钉截铁。～断魔爪。～敌者受赏。\n斩zhàn 1.沾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斩"},{"id":"glyph-kai-65ad","script":"kai","character":"断","reading":"duàn","description":"断开;断绝\n切肉肉断而发\n①长形东西从中截开折～、线～了。\n②断绝～水、关系～了。\n④判断；决断诊～、当机立～。\n⑤绝对～无此理。\n【断编残简】见【残篇断简】。\n【断层】岩层的连续性遭到破坏并沿破裂面有明显相对移动的一种断裂构造。根据断层两侧相对移动的性质可分为正断层、逆断层、平移断层等。\n【断层面】两部分岩块作相对移动的断裂面。\n【断层山】地壳断裂运动形成的块状山体。可分为地垒式断层山和掀斜式断层山。前者山坡为断层崖，后者山形不对称，断裂上升一侧为断层崖，另一侧为平缓山坡。又称断块\n山。\n【断层崖】〈地〉断层的上升盘突露地表而形成的悬崖。是由于断层线两边岩石受差别侵蚀形成的。断层崖因受垂直于断层面的流水侵蚀而形成v形谷。\n【断肠】形容极度思念、悲痛或忧伤。\n【断炊】没柴没米不能做饭。形容极为穷困。\n【断简残编】见【残篇断简】。\n【断简残篇】见【残篇断简】。\n【断交】绝交。常用于国际关系中。\n【断句】古书没有标点符号，诵读时根据文义作停顿，或同时在书上按停顿加圈点。这里的'句'与现代的'句'不尽相同。\n【断裂生殖】某些生物身体断裂后，每段均能生活，生长成新的个体，称为断裂生殖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-断"},{"id":"glyph-kai-65af","script":"kai","character":"斯","reading":"sī","description":"sī：(1)这，这个，这里～人。～时。以至于～。\n(2)乃，就有备～可以无患。\n(3)劈墓门有棘，斧以～之”。\n(4)古同厮”，卑贱。\n(5)古同澌”，尽。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-斯"},{"id":"glyph-kai-65b0","script":"kai","character":"新","reading":"xīn","description":"xīn：(1)刚有的，刚经验到的；初始的，没有用过的，与旧”、老”相对～生。～鲜。～奇。～贵。～绿。～星。～秀。～闻。～陈代谢。\n(2)性质改变得更好，与旧”相对改过自～。推陈出～。\n(3)不久以前，刚才～近。\n(4)表示一种有异于旧质的状态和性质～时代。～社会。～观念。～思维。\n(5)称结婚时的人或物～娘。～郎。～房。\n(6)中国新疆维吾尔自治区的简称。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-新"},{"id":"glyph-kai-65b9","script":"kai","character":"方","reading":"fāng","description":"fāng：(1)四个角都是90暗乃谋咝位蛄个面都是直角四边形的立体～材（亦称方子”）。～舟?(2)\n数学上指某数自乘的积～根。平～。开～。\n(3)人的品行端正～正。～直。\n(4)一边或一面～向。～面。\n(5)地区，地域地～。～志。～言。～物。～圆。～隅（边疆）。～舆（指领域，亦指大地）。\n(6)办法，做法，技巧～式。～法。教导有～。贻笑大～。\n(7)种，类变幻无～。仪态万～。\n(8)为治疗某种疾病而组合起来的若干种药物的名称、剂量和用法药～。\n(9)违背～命。\n(10)正在，正当～今盛世。～兴未艾。\n(11)才，刚刚～才。如梦～醒。\n(12)量词，多指一立方米土石～。\n(13)量词，用于方形的东西几～石章。\n(14)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-方"},{"id":"glyph-kai-65bd","script":"kai","character":"施","reading":"shī","description":"shī：(1)实行～工。～政。设～。～展。～教（jiào）。～为（wéi）。～威。实～。措～（办法）。发号～令。\n(2)用上，加工～肥。～粉。\n(3)给予～礼。～诊。～恩。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-施"},{"id":"glyph-kai-65c1","script":"kai","character":"旁","reading":"páng；bàng","description":"páng：(1)左右两侧～边。～侧。～门。～出。～听。～若无人。\n(2)其他，另外～人。～的话。触类～通。责无～贷。～证。～白（戏剧角色背着台上其他剧中人对观众说的话）。～落。\n(3)广，广泛～征博引。\n(4)邪、偏～门左道。\n(5)汉字形体中常常出现的某些组成部分偏～。竖心～儿。\nbàng：古同傍”，靠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旁"},{"id":"glyph-kai-65c5","script":"kai","character":"旅","reading":"lǚ；lv","description":"lǚ：(1)出行的，在外作客的～行（xíng）。～馆。～次。～居。～客。～伴。商～。差（chāi）～。～社。\n(2)军队的编制单位，在师与团之间。\n(3)泛指军队军～。强兵劲～。\n(4)共同～进～退。\n(5)同稆”。\n(6)古同膂”，脊梁骨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旅"},{"id":"glyph-kai-65cb","script":"kai","character":"旋","reading":"xuán；xuàn","description":"xuán：(1)转动～绕。～转。～舞。～梯。～律。盘～。天～地转。\n(2)回，归凯～。\n(3)不久～踵（喻极短的时间，如～～即逝”）。～即。\n(4)表示与各方来往或来往于各方之间周～。斡～。\n(5)古同漩”，漩涡。\n(6)姓。\nxuàn：(1)打转的～风。\n(2)临时（做）～吃～做。\n(3)用车床或刀子转着圈地削用车床～零件。把瓜皮～下去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旋"},{"id":"glyph-kai-65cf","script":"kai","character":"族","reading":"zú","description":"zú：(1)亲属，泛指同姓之亲～规。～长。家～。\n(2)指具有共同起源和共同遗传特征的人群种～。\n(3)指在历史上形成的人群的稳定共同体，他们有共同的语言、经济生活以及表现于共同文化上的心理素质民～。\n(4)聚居而有血统关系的人群的统称宗～。氏～。部～。\n(5)事物有共同属性的一大类芳香～。\n(6)封建时代的一种残酷刑罚，一人有罪，把全家或包括母亲、妻家的人都杀死～灭。\n(7)聚合，集中云气不待～而雨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-族"},{"id":"glyph-kai-65d7","script":"kai","character":"旗","reading":"qí","description":"qí：(1)用布、纸、绸子或其他材料做成的标识（zhì），多是长方形或方形～子。～帜。～号。～舰。～手。\n(2)中国清代满族的军队编制和户口编制（共分八旗，后又建立蒙古八旗，汉军八旗），特指属于满族的～人（满族人）。～籍。～袍。\n(3)中国内蒙古自治区的行政区划，相当于县。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旗"},{"id":"glyph-kai-65e0","script":"kai","character":"无","reading":"wú","description":"哲学范畴,指无形、无名、虚无等,或指物质的隐微状态\n没有,跟有”相对\n无不变色。\n无不毕肖。\n⒈没有，跟\"有\"相对～粮～钱。～穷～尽。\n⒉不～仿说出。\n⒊不分，不论，不外～分。～论，地～四方。民～异国。事～大小。～非如此。\n⒋通\"毋\"。不，不要～往。\n无mó 1.见\"南无\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-无"},{"id":"glyph-kai-65e2","script":"kai","character":"既","reading":"jì","description":"jì：(1)动作已经完了～往不咎。～而。\n(2)已经～成事实。～定。\n(3)常与且”、又”连用，表示两者并列～快又好。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-既"},{"id":"glyph-kai-65e5","script":"kai","character":"日","reading":"rì","description":"太阳，也指一天。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-65e6","script":"kai","character":"旦","reading":"dàn","description":"dàn：(1)早晨～暮。通宵达～。枕戈待～。\n(2)表示某一天，亦指农历的初一日～望（农历的初一和十五日）。元～。～日（ａ．明天ｂ．白天）。\n(3)传统戏剧里扮演女子的角色老～。花～。\n(4)纤度单位，九千米长的纤维重量为多少克，它的纤度就是多少旦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旦"},{"id":"glyph-kai-65e7","script":"kai","character":"旧","reading":"jiù","description":"鸺鷙,即猫头鹰\n故交,老交情\n原有的典章制度\n指世族\n通丘”。丘冢,坟墓\n越王\n⒈陈的，过时的，跟\"新\"相对～的。～日。守～。～调重弹。〈引〉原来的，从前的～山河。～地重游。～恨新仇。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旧"},{"id":"glyph-kai-65e8","script":"kai","character":"旨","reading":"zhǐ","description":"zhǐ：(1)意义，目的意～。要～。主～。言近～远。\n(2)封建时代称帝王的命令～令。奉～。\n(3)美味～酒。甘～。～蓄（贮藏的美好食品）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旨"},{"id":"glyph-kai-65e9","script":"kai","character":"早","reading":"zǎo","description":"zǎo：(1)太阳出来的时候～晨。～晚。\n(2)时间靠前，有一定的时间以前～退。～恋。～慧（幼时聪明）。～衰。～逝（早死）。\n(3)时间在先的，从前～期。～春。～已。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-早"},{"id":"glyph-kai-65ec","script":"kai","character":"旬","reading":"xún","description":"xún：(1)十日为一旬（一个月分三旬）上～。中～。下～。～刊。\n(2)十岁为一旬年过六～。八～老者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旬"},{"id":"glyph-kai-65ed","script":"kai","character":"旭","reading":"xù","description":"xù：(1)光明，早晨太阳才出来的样子～日东升。朝（zhāo）～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旭"},{"id":"glyph-kai-65f1","script":"kai","character":"旱","reading":"hàn","description":"hàn：(1)长时间不下雨，缺雨，缺水，与涝”相对～季。～灾。干～。防～。\n(2)非水田的、无水的、陆地上的，与水无关的～井。～田。～獭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旱"},{"id":"glyph-kai-65f6","script":"kai","character":"时","reading":"shí","description":"⒈一切物质不断运动变化或发展所经历的过程～间。～候。～光。\n⒉时间的一段～期。～代。古～。秦～。平～。瞬～。盛极一～。\n⒊时间单位。一天分子～、丑～、寅～等十二～辰。一天分二十四小～。\n⒋节令，季节～令。～节。春夏秋冬四～。应～服装。\n⒌现在的，当前的～事。～髦。\n⒍经常，常常～常。～ ～见到。\n⒎不经常，间或～而。有～候。～好～坏。\n⒏规定的时间准～。按～上下班。\n⒐不定的时间不～。随～。\n⒑机会，具有时间性的有利条件～机。～不可失。～不再来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-时"},{"id":"glyph-kai-65f7","script":"kai","character":"旷","reading":"kuàng","description":"心境开阔,开朗\n空旷;开阔\n率彼旷\n⒈广大，空阔～野荒郊。空～无人。土地平～。\n⒊空缺，荒废久～。～课。～工。～日持久。\n⒋历时久远～年。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旷"},{"id":"glyph-kai-65fa","script":"kai","character":"旺","reading":"wàng","description":"wàng：盛，兴盛～年（水果等丰收的年份，俗称大年”）。～盛（shèng）。兴～。～季。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-旺"},{"id":"glyph-kai-6602","script":"kai","character":"昂","reading":"áng","description":"áng：(1)仰，高抬～首。～然。\n(2)高，贵～贵。价～。\n(3)情绪高～扬。高～。～藏（cáng）（形容人的仪表雄伟，气宇不凡的样子）。～奋。气～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昂"},{"id":"glyph-kai-6606","script":"kai","character":"昆","reading":"kūn","description":"kūn：(1)子孙，后嗣～裔（子孙后代）◇～。\n(2)哥哥～弟（ａ．兄弟；ｂ．友好亲爱）。～仲。～季。～玉（称人兄弟的敬辞）。\n(3)众多～虫（虫类的统称）。\n(4)山名（ａ．昆山”，在中国上海市和江苏省；ｂ．昆仑山”，在中国新疆维吾尔自治区、西藏自治区和青海省交界处，亦作崑??山”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昆"},{"id":"glyph-kai-660c","script":"kai","character":"昌","reading":"chāng","description":"chāng：(1)兴盛～盛（shèng）。～乐（lè）（兴盛康乐）。～明（兴盛发达）。～隆。\n(2)善，正当～言（美言，正当的话）。～言无忌（直言无隐）。\n(3)古同菖”，菖蒲。\n(4)古同猖”，凶猛。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昌"},{"id":"glyph-kai-660e","script":"kai","character":"明","reading":"míng","description":"明亮，也有清楚、明白之意。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-660f","script":"kai","character":"昏","reading":"hūn","description":"hūn：(1)天刚黑的时候黄～。～晓（朝夕。亦指明暗）。～定晨省（xǐng）（人子侍奉父母的日常礼节，晚上服侍就寝，早上省视问安）。\n(2)暗而无光～暗。～黑。\n(3)惑乱～愦。～聩。～庸。\n(4)神智不清楚或失去知觉发～。～厥（亦称晕厥”）。～乱。\n(5)古同婚”，婚姻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昏"},{"id":"glyph-kai-6613","script":"kai","character":"易","reading":"yì","description":"yì：(1)不费力，与难”相对容～。～与（容易对付）。～于。\n(2)和悦平～（ａ．态度谦逊和蔼；ｂ．指语言文字浅显）。\n(3)改变～手。～地。变～。\n(4)交换交～。贸～。\n(5)轻慢贵货～土。\n(6)芟治草木～墓（除治墓地的草木）。～其田畴。\n(7)古书名，《周易》的简称（亦称易经”）。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-易"},{"id":"glyph-kai-6614","script":"kai","character":"昔","reading":"xī","description":"xī：(1)以前，从前～者。～人。往～。今～对比。\n(2)古同夕”，夜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昔"},{"id":"glyph-kai-661f","script":"kai","character":"星","reading":"xīng","description":"星辰，夜空中可见的星体。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6620","script":"kai","character":"映","reading":"yìng","description":"yìng：(1)照射～射。～照。\n(2)反照，照射而显示反～（ａ．反照，反射；ｂ．把容观事物表现出来；ｃ．向上级转达，如～～群众意见”）。～衬（映托使显现）。～雪读书（形容家贫而苦读）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-映"},{"id":"glyph-kai-6625","script":"kai","character":"春","reading":"chūn","description":"一年四季中的春季，草木萌发生长的时节。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6627","script":"kai","character":"昧","reading":"mèi","description":"mèi：(1)暗，不明幽～。～旦（清晨还未明亮时）。\n(2)昏，糊涂，不明白愚～。蒙～。素～平生（一向不认识）。\n(3)目不明目不别五色之章为～”。\n(4)隐藏，隐瞒暧～。～心（违背良心做坏事）。\n(5)冒犯冒～（多作谦辞）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昧"},{"id":"glyph-kai-6628","script":"kai","character":"昨","reading":"zuó","description":"zuó：今天的前一天，亦泛指过去～天。觉今是而～非（感到现在这样是对的，过去是错误的）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昨"},{"id":"glyph-kai-662d","script":"kai","character":"昭","reading":"zhāo","description":"zhāo：(1)光明～明。～～（ａ．明亮的样子，如日月～～”；ｂ．明白事理。如贤者以其～～，使人～～”）。\n(2)明显，显著～著。～彰。～布。～雪（揭明真情，洗清冤枉）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昭"},{"id":"glyph-kai-662f","script":"kai","character":"是","reading":"shì","description":"shì：(1)表示解释或分类他～工人。《阿Ｑ正传》的作者～鲁迅。\n(2)表示存在满身～汗。\n(3)表示承认所说的，再转入正意，含有虽然”的意思诗～好诗，就是太长了。\n(4)表示适合来的～时候。\n(5)表示任何凡～。～活儿他都肯干。\n(6)用于问句他～走了吗？\n(7)加重语气，有的确”、实在”的意思天气～冷。\n(8)对，合理，与非”相对～非。他说的～。实事求～。\n(9)认为对～古非今。各行其～。深～其言。\n(10)表示应承或同意（单说一个是”字）～，我就去。\n(11)这，此～日。～可忍，孰不可忍。比比皆～。\n(12)助词，把行为对象提前表示只这样做惟你～问。惟利～图。\n(13)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-是"},{"id":"glyph-kai-663c","script":"kai","character":"昼","reading":"zhòu","description":"中午、正午","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-昼"},{"id":"glyph-kai-663e","script":"kai","character":"显","reading":"xiǎn","description":"表面,外面\n明显;显示得很清楚\n⒈露在外面，易于看出～露。～明。～著。～然。～而易见。\n⒉表现～示。～现。大～身手。\n⒊有声望、有地位的，旧称有权有势的～扬。～达。～赫。～贵。～宦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-显"},{"id":"glyph-kai-6643","script":"kai","character":"晃","reading":"huàng；huǎng","description":"huǎng：(1)明亮明～～。\n(2)照耀～眼。\n(3)形影很快地闪过一～十年。\n摆；摇；\nhuàng：摇动～荡。～动。～悠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晃"},{"id":"glyph-kai-664b","script":"kai","character":"晋","reading":"jìn","description":"jìn：(1)进～级。～升。～谒（进见）。\n(2)中国周代诸侯国名。\n(3)中国山西省的别称～剧。\n(4)中国朝代名西～。东～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晋"},{"id":"glyph-kai-664c","script":"kai","character":"晌","reading":"shǎng","description":"shǎng：(1)一天内的一段时间，一会儿工作了半～。\n(2)正午或正午前后～午。～饭。～觉。歇～。\n(3)古同垧”，计算地亩的单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晌"},{"id":"glyph-kai-6652","script":"kai","character":"晒","reading":"shai","description":"暴晒;晒干","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晒"},{"id":"glyph-kai-6653","script":"kai","character":"晓","reading":"xiǎo","description":"清晨\n晓光浮\n⒈天亮拂～。天～。\n⒉知道，明白～得。家喻户～。\n⒊告知～以利弊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晓"},{"id":"glyph-kai-6655","script":"kai","character":"晕","reading":"yūn","description":"昏倒\n日月周围的光圈\n环形花纹或波纹\n⒈昏迷～倒。～厥。\n⒈日光或月光通过云层因折射作用而看到日或月周围形成的光圈日～。月～。\n⒉头发昏～车。～船。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晕"},{"id":"glyph-kai-665a","script":"kai","character":"晚","reading":"wǎn","description":"wǎn：(1)太阳落了的时候～景。～霞。～会。～报。\n(2)一个时期的后段，在一定时间以后来～了。～年。～期。～节。～婚。\n(3)后来的～生（旧时文人对前辈的自谦）。～辈。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晚"},{"id":"glyph-kai-6666","script":"kai","character":"晦","reading":"huì","description":"huì：(1)农历每月的末一天，朔日的前一天～朔。\n(2)夜晚～明。风雨如～。\n(3)昏暗不明～暝。～暗。～涩（意义隐晦，文字僻拗）。隐～（意义不明显）。\n(4)不顺利，倒霉～气。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晦"},{"id":"glyph-kai-6668","script":"kai","character":"晨","reading":"chén","description":"chén：清早，太阳出来的时候早～。凌～。～光。～曦（晨光）。～风。～雾。～炊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晨"},{"id":"glyph-kai-666e","script":"kai","character":"普","reading":"pǔ","description":"pǔ：全，广，遍～遍。～通。～查。～照。～天同庆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-普"},{"id":"glyph-kai-666f","script":"kai","character":"景","reading":"jǐng；yǐng","description":"jǐng：(1)环境的风光～色。～致。～物。～观。～气（ａ．景色；ｂ．指经济繁荣现象，统指兴旺）。～深。\n(2)情况，状况～象。～况。年～。\n(3)佩服，敬慕～仰。～慕。\n(4)高，大～行（xíng）。\n(5)姓。\nyǐng：古同影”，影子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-景"},{"id":"glyph-kai-6670","script":"kai","character":"晰","reading":"xī","description":"xī：明白，清楚清～。明～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晰"},{"id":"glyph-kai-6674","script":"kai","character":"晴","reading":"qíng","description":"qíng：天空中无云或云很少～天。～朗。～和。～丽。～爽。～碧。～雨表。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晴"},{"id":"glyph-kai-6676","script":"kai","character":"晶","reading":"jīng","description":"jīng：形容光亮～莹。～亮。～明。亮～～。\n〔结～〕ａ．物质从液态或气态形成晶体；ｂ．喻珍贵的成果，如这部作品是他多年研究的～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晶"},{"id":"glyph-kai-667a","script":"kai","character":"智","reading":"zhì","description":"zhì：聪明，见识～力。～慧。～商。～育。～能。～谋。才～。机～。理～。明～（ａ．考虑问题周到、严密；ｂ．有远见）。足～多谋。利令～昏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-智"},{"id":"glyph-kai-667e","script":"kai","character":"晾","reading":"liàng","description":"liàng：把衣服等放在阳光下，或放在通风透气的地方使干～晒。～干。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-晾"},{"id":"glyph-kai-6682","script":"kai","character":"暂","reading":"zàn","description":"暂时\n求假暂归。\n刚刚;方才","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暂"},{"id":"glyph-kai-6687","script":"kai","character":"暇","reading":"xiá","description":"xiá：空闲，没有事的时候得～。闲～。无～。应接不～。目不～接。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暇"},{"id":"glyph-kai-6691","script":"kai","character":"暑","reading":"shǔ","description":"shǔ：(1)热～天。～热。～假。酷～。\n(2)中医学六淫”之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暑"},{"id":"glyph-kai-6696","script":"kai","character":"暖","reading":"nuǎn","description":"nuǎn：(1)温和，不冷～和。温～。～色。～洋洋。\n(2)使温和～酒。～一～手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暖"},{"id":"glyph-kai-6697","script":"kai","character":"暗","reading":"àn","description":"àn：(1)不亮，没有光，与明”相对黑～。～淡（ａ．不光明；ｂ．喻景象悲惨）。阴～。～无天日。\n(2)不公开的，隐藏不露的～藏。～号。～杀。～娼。～沟。～含（做事、说话包含某种意思而未明白说出）。～流（ａ．流动的地下水；ｂ．喻潜伏的思想倾向或社会动态）。明察～访。\n(3)愚昧，糊涂～昧。～弱（愚昧软弱）。兼听则明，偏信则～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暗"},{"id":"glyph-kai-66ae","script":"kai","character":"暮","reading":"mù","description":"mù：(1)傍晚，太阳落山的时候日～。～气。～色。日～途穷。～鼓晨钟。\n(2)晚，将尽～春。～年。～节。～齿（晚年）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暮"},{"id":"glyph-kai-66b4","script":"kai","character":"暴","reading":"bào；pù","description":"bào：(1)强大而突然来的，又猛又急的～雷。～病。～动。～力。～涨。～发。风～。～风骤雨（亦喻声势浩大、发展迅猛的群众运动）。\n(2)过分急躁的，容易冲击的脾气～躁。～跳如雷。\n(3)凶恶残酷的凶～。～虐。～君。～戾恣睢（残暴凶狠，任意胡为）。～政♂征～敛。\n(4)横蹋，损害自～自弃。～殄天物（任意糟蹋东西）。\n(5)鼓起来，突出～起青筋。\n(6)徒手搏击～虎冯（pīng）河（喻有勇无谋）。\n(7)姓。\n〔～露〕显露，如～～无遗”。\npù：同曝1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-暴"},{"id":"glyph-kai-66d9","script":"kai","character":"曙","reading":"shǔ","description":"shǔ：天刚亮～色。～光（破晓之光，喻已经在望的美好前景）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曙"},{"id":"glyph-kai-66dd","script":"kai","character":"曝","reading":"pù；bào","description":"pù：晒～晒（用强烈阳光照晒）。一～十寒（喻无恒心）。\nbào：〔～光〕使感光纸或摄影胶片感光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曝"},{"id":"glyph-kai-66f0","script":"kai","character":"曰","reading":"yuē","description":"yuē：(1)说子～诗云。\n(2)为（wéi），是一～水，二～火，三～木，四～金，五～土。\n(3)叫做凡乐辞～诗，诗声～歌。\n(4)语助词，无实义昊天～明。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曰"},{"id":"glyph-kai-66f2","script":"kai","character":"曲","reading":"qǔ","description":"qǔ：(1)能唱的文词，一种艺术形式～艺。～话。\n(2)歌的乐调～调（diào）。～谱。异～同工。～高和（hè）寡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曲"},{"id":"glyph-kai-66f4","script":"kai","character":"更","reading":"gèng；gēng","description":"gēng：(1)改变，改换～正。～生（重新获得生命，喻复兴）。～衣（ａ．换衣服；ｂ．婉辞，上厕所）。～定（改订）。～迭（轮流更换）。～递。～番。～新（旧的除去，新的建起）。～张（调节琴弦，喻变更或改革）。\n(2)经历少（shào）不～事（年龄小，没有经历过多少事情）。\n(3)旧时夜间计时单位，一夜分为五更～时。～阑。～夫。～鼓。～漏（原指计时用的漏壶，后泛指时辰）。\ngèng：愈加，再～加。～好。～上一层楼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-更"},{"id":"glyph-kai-66f9","script":"kai","character":"曹","reading":"cáo","description":"cáo：(1)等，辈尔～（你们）。吾～。\n(2)古代分科办事的官署部～（中国明、清两代各部司曹的通称，源于汉代曹史的简称，相当于郡守的总务长）。\n(3)诉讼的原告、被告两方。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曹"},{"id":"glyph-kai-66fc","script":"kai","character":"曼","reading":"màn","description":"màn：(1)长，延长～延。～声而歌。\n(2)美，柔美～妙。～靡。～辞。轻歌～舞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曼"},{"id":"glyph-kai-66fe","script":"kai","character":"曾","reading":"céng；zēng","description":"zēng：(1)指与自己中间隔两代的亲属～祖父。～孙。\n(2)古同增”，增加。\n(3)竟，简直，还（hái）以君之力～不能损魁父之丘，如太山、王屋何？”\n(4)姓。\ncéng：(1)尝，表示从前经历过～经。未～∥～。～几何时。\n(2)古同层”，重（chóng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-曾"},{"id":"glyph-kai-66ff","script":"kai","character":"替","reading":"tì","description":"tì：(1)代，代理代～。更（gēng）～。。～班。～身。～罪羊。\n(2)为，给～他送行。～古人担忧。\n(3)衰废兴（xīng）～。衰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-替"},{"id":"glyph-kai-6700","script":"kai","character":"最","reading":"zuì","description":"zuì：(1)极，无比的～大。～高。～初。～终。～为（wéi）。\n(2)聚合忧喜～门。\n(3)合计～大将军青凡七出击匈奴”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-最"},{"id":"glyph-kai-6708","script":"kai","character":"月","reading":"yuè","description":"月亮，也指月份。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-6709","script":"kai","character":"有","reading":"yǒu；yòu","description":"yǒu：(1)存在～关。～方（得法）。～案可稽。～备无患。～目共睹。\n(2)表示所属他～一本书。\n(3)表示发生、出现～病。情况～变化。\n(4)表示估量或比较水～一丈多深。\n(5)表示大、多～学问。\n(6)用在某些动词前面表示客气～劳。～请。\n(7)无定指，与某”相近～一天。\n(8)词缀，用在某些朝代名称的前面～夏。～宋一代。\n无；没；\nyòu：古同又”，表示整数之外再加零数。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-有"},{"id":"glyph-kai-670b","script":"kai","character":"朋","reading":"péng","description":"péng：(1)彼此友好的人～友。～辈。～侪。～俦。宾～。至爱亲～。\n(2)结党～党（为私利而互相勾结、排斥异己的一帮人）。\n(3)成群群居～飞。\n(4)古代以贝壳为货币，五贝为一串，两串为一朋。\n(5)比硬大无～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朋"},{"id":"glyph-kai-670d","script":"kai","character":"服","reading":"fú；fù","description":"fú：(1)衣裳～装。制～。\n(2)穿衣裳～丧。～用（ａ．指穿衣服、用器物；ｂ．吃药）。\n(3)作，担任～务。～刑。～兵役。\n(4)顺从信～。佩～。降（xiáng）～。～辩（旧指认罪书）。～膺（牢记在胸中，衷心信服）。\n(5)习惯，适应不～水土。\n(6)吃（药）内～。\n(7)乘，用～牛乘（chéng）马。\n(8)姓。\nfù：量词，指中药（亦作付”）两～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-服"},{"id":"glyph-kai-6717","script":"kai","character":"朗","reading":"lǎng","description":"lǎng：(1)明亮，光线充足～敞。～澈。～然。明～。晴～。开～。爽～。\n(2)声音清楚、响亮～声。～读。～诵。书声～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朗"},{"id":"glyph-kai-671b","script":"kai","character":"望","reading":"wàng","description":"wàng：(1)看，往远处看～见。眺～。张～。～尘莫及（喻远远落后）。～风捕影。\n(2)拜访看～。拜～。探～。\n(3)希图，盼期～。欲～。喜出～外。\n(4)人所敬仰的，有名的～族。名～。声～。威～。\n(5)向，朝着～东走。\n(6)月圆，农历每月十五日前后～日。\n(7)埋怨，责备怨～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-望"},{"id":"glyph-kai-671d","script":"kai","character":"朝","reading":"cháo；zhāo","description":"cháo：朝向；朝见；朝廷、朝代。zhāo：早晨，如朝阳、朝夕。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-671f","script":"kai","character":"期","reading":"qī；jī","description":"qī：(1)规定的时间，或一段时间定～。限～。～限。学～。\n(2)量词，用于刊物或其他分期的事物第五～。\n(3)盼望，希望～望。～冀。～盼。～待。\n(4)限度征敛无～求索无度”。\n(5)必，决定～死，非勇也”。\n(6)地质学上指在一个国境内或一个大区域内，小于世”的地质年代单位。\n〔～颐〕指人活到一百岁。\njī：一周年，一整月～年。～月。～服（古代丧服名，要穿一年）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-期"},{"id":"glyph-kai-6726","script":"kai","character":"朦","reading":"méng","description":"méng：〔～胧〕ａ．月光不明；ｂ．不清楚，凝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朦"},{"id":"glyph-kai-6728","script":"kai","character":"木","reading":"mù","description":"mù：(1)树类植物的通称树～。乔～。灌～。～石（树木和石头，喻没有知觉和情感的东西）。缘～求鱼。\n(2)木料、木制品～材。～器。～刻。～匠。～已成舟。\n(3)棺材棺～。\n(4)质朴～讷（朴实迟钝）。\n(5)呆笨～鸡。\n(6)感觉不灵敏，失去知觉麻～。\n(7)中国古代乐器八音之一。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-木"},{"id":"glyph-kai-672a","script":"kai","character":"未","reading":"wèi","description":"wèi：(1)不，不曾，没有～必。～曾（céng）。～来。～尝。～竟（没有完成的）。～及（ａ．没有来得及；ｂ．没有达到）。\n(2)地支的第八位，属羊。\n(3)用于记时～时（下午一点至三点）。\n(4)放在句末，表示疑问君除吏尽～？吾亦欲除吏”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-未"},{"id":"glyph-kai-672b","script":"kai","character":"末","reading":"mò","description":"mò：(1)尖端，梢～梢。～端。秋毫之～（毫毛尖端）。\n(2)最后，终了～了（liǎo）。～尾。～日。～代。穷途～路。\n(3)非根本的，次要的，差一等的～业。～技。舍本逐～。\n(4)碎屑～子。碎～。\n(5)传统戏剧角色名，一般扮演中年以上男子正～。副～。外～。～本（以男角主唱的杂剧）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-末"},{"id":"glyph-kai-672c","script":"kai","character":"本","reading":"běn","description":"běn：(1)草木的根～草（泛指中药）。无～之木。\n(2)事物的根源，与末”相对～末（头尾；始终）。根～（根源；彻底；本质上）。\n(3)草的茎，树的干草～植物。\n(4)中心的，主要的～部。～体。\n(5)原来～来。～领。\n(6)自己这方面的～国。～身。～位。～分（fèn）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-本"},{"id":"glyph-kai-672f","script":"kai","character":"术","reading":"shù；shú；zhú","description":"shù：(1)技艺技～。艺～。武～。学～。不学无～。\n(2)方法战～。权～。心～。\n(3)古代城市中的道路。\nshú：古同秫”，黏高梁。\nzhú：〔白～〕多年生草本植物，根状茎可入药。\n〔苍～〕多年生草本植物，根状茎可入药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-术"},{"id":"glyph-kai-6731","script":"kai","character":"朱","reading":"zhū；shú","description":"shú：〔～提（shí）〕古地名，在今中国四川宜宾市，产银，故银亦称朱提”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朱"},{"id":"glyph-kai-6734","script":"kai","character":"朴","reading":"pǔ；pò；pō；piáo","description":"pò：落叶乔木，叶椭圆形，上部边缘有锯齿，花细小，色淡黄，果实球形，黑色，味甜可食。木材可制器具。\npō：〔～刀〕古代的一种武器，窄长有短把的刀，双手使用。\npiáo：姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朴"},{"id":"glyph-kai-6735","script":"kai","character":"朵","reading":"duǒ","description":"duǒ：(1)植物的花或苞花～。～儿。\n(2)量词，指花或成团的东西三～花。\n(3)动～颐（指动腮颊嚼东西吃的样子）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朵"},{"id":"glyph-kai-673a","script":"kai","character":"机","reading":"jī","description":"木名。桤木树\n通几”。几案,小桌子\n⒈〈古〉弓弩上发射箭的机关操弓关～。〈引〉作战设备或其它机械。又特指织布机。\n⒉关键，要点生～。危～。治乱之～。〈引〉\n①保密的或有重要关系的环节～密文件。军～大事。\n②正合适的时候～会。时～。随～应变。～不可失。\n⒊灵巧～灵。～智。～敏。\n⒋机器，由若干零件组成可以做功，或具有特殊作用的装置或设备～床。发电～。电子计算～。\n⒌事情的苗头或预兆～兆。\n⒍事务日理万～。\n①使用机器开动的～动船。\n②随时灵活行动的或准备灵活运用的～动部队。～动处置。～动款。\n①控制整个机器的关键，也指某种有自动装置的器械和设备那里是这部机器的～关。暗设～关。\n②办理事务的机构或单位缩简行政～关。\n③计谋，计策～关算尽太聪明，反误了卿卿性命。\n①机械的内部构造。\n②泛指机关、团体等工作单位，也指它的内部组织精简～构。\n①各种机器、装置、设备的总称化工～械。工业～械。农业～械。\n②呆板，不灵活，工作方式方法固定、老一套没有变化～械的工作。\n机wèi 1.砧板。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-机"},{"id":"glyph-kai-673d","script":"kai","character":"朽","reading":"xiǔ","description":"xiǔ：(1)腐烂腐～。～木。永垂不～（朽”在此引申为磨灭）。\n(2)衰老衰～。～迈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-朽"},{"id":"glyph-kai-6740","script":"kai","character":"杀","reading":"shā","description":"然得而腊之以为饵,可以已大风、挛踠、瘘、疠,去死肌,杀三虫\n⒈弄死，使失去生命～敌。～猪。～虫剂。\n⒉战斗～退侵略军。～出重围。\n⒊消减，残败～风景。～威风。我花开后百花～。\n⒋收束，断绝～帐。～尾。\n⒌勒紧，扣紧～一～带子。\n⒍药物等刺激身体感到疼痛擦了这种药后～得慌。\n⒎在动词后。〈表〉程度深愁～人。喜～人。\n①凶恶的气势～气腾腾。\n②发泄不愉快的情绪你拿谁～气？\n杀sà 1.散落;散布。 2.古代为护城而设置的防卫据点。 3.枯干貌。\n杀shì 1.古指臣杀君﹑子杀父的行为。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杀"},{"id":"glyph-kai-6742","script":"kai","character":"杂","reading":"zá","description":"混合;搀杂\n聚会;聚集\n驳杂不纯\n⒈不单纯的，各种各样的～事。～色。～粮。～技。人多太～。\n⒉渗入，混合搀～。混～。\n⒊交错长短相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杂"},{"id":"glyph-kai-6743","script":"kai","character":"权","reading":"quán","description":"秤。测定物体重量的器具\n谨权量、审法度、修废官,四方之政行\n⒈掌握、支配和指挥的力量～力。～柄。～势。政～。职～。\n⒉权利发言～。选举～。\n⒊势力，有利形势制空～。主动～。\n⒋暂且，灵活，变通～且。～宜。～变。\n⒌〈古〉指秤，秤锤铜～。〈引〉衡量 ～衡轻重。\n①最有威望或力量～威人士。\n②在某种范围里最有地位的人或事物学术～威。\n权guàn 1.权火，烽火。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-权"},{"id":"glyph-kai-6746","script":"kai","character":"杆","reading":"gǎn；gān","description":"gān：较长的棍～子（ａ．长棍；ｂ．方言，指揭竿而起的人；ｃ．指结伙抢劫的土匪）。旗～。桅～。电线～。\ngǎn：(1)器物上像棍子的细长部分～秤（区别于台秤等）。笔～儿。～菌。\n(2)量词，用于有杆的器物一～笔。一～步枪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杆"},{"id":"glyph-kai-6749","script":"kai","character":"杉","reading":"shān；shā","description":"shān：常绿乔木，树干很高很直。木材白色，质轻，有香味，可供建筑和制器具用。\nshā：义同（一）～木。～篙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杉"},{"id":"glyph-kai-674e","script":"kai","character":"李","reading":"lǐ","description":"lǐ：(1)落叶小乔木，果实称李子”，熟时呈黄色或紫红色，可食～代桃僵（原用桃”李”共患难来喻兄弟相爱相助，后喻互相顶替或代他人受过）。投桃报～。～下不正冠（喻要避免不必要的嫌疑）。桃～不言，下自成蹊（喻为人只要忠诚、正直一定会感动别人）。\n(2)姓。\n(3)古同理”，古代法官的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-李"},{"id":"glyph-kai-674f","script":"kai","character":"杏","reading":"xìng","description":"xìng：落叶乔木，叶卵形，花白色或淡红色，果实称杏儿”、杏子”，酸甜，可食～仁儿。～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-杏"},{"id":"glyph-kai-6750","script":"kai","character":"材","reading":"cái","description":"cái：(1)木料，泛指一切原料或资料～料。教（jiào）～。素～。题～。就地取～。\n(2)能力，资质～干（gàn）。大～小用。因～施教（jiào）。\n(3)棺木寿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-材"}];
